#include <bits/stdc++.h>
using namespace std;
#define ll long long
int main() {
	// your code goes here
	int t;
	cin >> t;
	while(t--) {
	    int n;
	    cin >> n;
	    vector<ll> a(3*n);
	    for(int i = 0;i < 3*n; i++) {
	        cin >> a[i];
	    }
	    ll ans = 0;
	    vector<ll> S(3*n + 1 , 0);
	    sort(a.rbegin() , a.rend());
	    for(int i = 0;i < 3*n; i++) {
	        S[i + 1] = S[i] + a[i];
	    }
	    
	    ll mx = 0;
	    for(ll k = n; k <= 3LL*n; k++) {
	        ll l = max(0LL, 2LL *n - k);
	        ll r = (3LL * n - k) / 2LL;
	        
	        if(l > r) continue;
	        auto eval = [&](ll x) {
	            ll idx = 6LL*n - 2LL*k - 3LL*x;
	            return 2LL*S[x] + S[idx];
	        };
	        
	        ll low = l , high = r;
	        while(low < high) {
	            ll mid = low + (high - low) / 2;
	            if(eval(mid + 1) > eval(mid)) {
	                low = mid + 1;
	            }
	            else {
	                high = mid;
	            }
	        }
	        ll curr = eval(low) + 3LL * S[k];
	        mx = max(mx , curr);
	    }
	    cout << mx << endl;
	    
	    
	}

}
